import os
import sys
import time
import webbrowser
from datetime import datetime

LOG_DIR = "./target"
LOG_FILE = "reminder_tool.log"

def log_message(message):
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
        with open(os.path.join(LOG_DIR, LOG_FILE), "a") as log_file:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception as e:
        print(f"Error: Unable to write to log file. {e}", file=sys.stderr)

def open_url(url):
    try:
        if webbrowser.open(url):
            log_message(f"Successfully opened URL: {url}")
            print(f"Successfully opened URL: {url}")
        else:
            log_message(f"Failed to open URL: {url}")
            print(f"Failed to open URL: {url}", file=sys.stderr)
    except Exception as e:
        log_message(f"Error: Could not open URL {url}. Exception: {e}")
        print(f"Error: Could not open URL. {e}", file=sys.stderr)

def detach_process():
    if os.name != 'nt':
        # Detach from terminal on Unix-like systems
        try:
            pid = os.fork()
            if pid > 0:
                sys.exit(0)  # Parent process exits
        except OSError as e:
            print(f"Error: Unable to fork process. {e}", file=sys.stderr)
            sys.exit(1)
        os.setsid()
        pid = os.fork()
        if pid > 0:
            sys.exit(0)  # Parent process exits
        sys.stdout.flush()
        sys.stderr.flush()
        with open(os.devnull, 'r') as devnull:
            os.dup2(devnull.fileno(), sys.stdin.fileno())
        with open(os.devnull, 'a') as devnull:
            os.dup2(devnull.fileno(), sys.stdout.fileno())
            os.dup2(devnull.fileno(), sys.stderr.fileno())

def main():
    if len(sys.argv) < 2 or len(sys.argv) > 4:
        print("Usage: python script.py <URL> [interval_seconds] [attempts]", file=sys.stderr)
        log_message("Error: Incorrect number of arguments provided.")
        sys.exit(1)

    url = sys.argv[1]
    interval = int(sys.argv[2]) if len(sys.argv) >= 3 else 3600
    attempts = int(sys.argv[3]) if len(sys.argv) == 4 else 1

    detach_process()

    for attempt in range(attempts):
        log_message(f"Attempt {attempt + 1} to open URL: {url}")
        open_url(url)
        if attempt < attempts - 1:
            time.sleep(interval)

if __name__ == "__main__":
    main()

import os
import sys
import time
import urllib.request
import json

STATE_FILE = './target/state.json'

def load_state():
    if os.path.exists(STATE_FILE):
        try:
            with open(STATE_FILE, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error loading state file: {e}")
    return {"completed_iterations": 0}

def save_state(state):
    try:
        with open(STATE_FILE, 'w') as f:
            json.dump(state, f)
    except Exception as e:
        print(f"Error saving state file: {e}")

def download_file(url, target_directory, notification_url):
    try:
        if not os.path.exists(target_directory):
            os.makedirs(target_directory)

        filename = os.path.basename(url)
        if not filename:
            print("Error: Unable to determine filename from URL.")
            sys.exit(1)

        filepath = os.path.join(target_directory, filename)
        urllib.request.urlretrieve(url, filepath)
        print(f"File downloaded successfully: {filepath}")
        print(f"Visit the notification URL: {notification_url}")

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

def main():
    if len(sys.argv) < 3:
        print("Usage: python download.py <URL> <Notification_URL> [--interval=<seconds>] [--iterations=<count>] [--persist]")
        sys.exit(1)

    url = sys.argv[1]
    notification_url = sys.argv[2]
    target_directory = './target'

    # Parse optional arguments
    interval = 0
    max_iterations = 1
    persist = False

    for arg in sys.argv[3:]:
        if arg.startswith("--interval="):
            interval = int(arg.split("=")[1])
        elif arg.startswith("--iterations="):
            max_iterations = int(arg.split("=")[1])
        elif arg == "--persist":
            persist = True

    state = load_state() if persist else {"completed_iterations": 0}

    for i in range(state["completed_iterations"], max_iterations):
        print(f"Starting iteration {i + 1}...")
        download_file(url, target_directory, notification_url)
        state["completed_iterations"] = i + 1
        if persist:
            save_state(state)
        if interval > 0 and i + 1 < max_iterations:
            time.sleep(interval)

    print("All iterations completed.")

if __name__ == "__main__":
    main()

import time
import argparse
import logging
import os

def setup_logging():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s"
    )

def process_notification(event_id, message, log_file):
    keywords = {"notification", "notify", "alert"}
    if any(keyword in message.lower() for keyword in keywords):
        try:
            with open(log_file, "a") as file:
                file.write(f"Event {event_id}: {message}\n")
            return True
        except (IOError, OSError) as e:
            logging.error(f"Failed to write to log file '{log_file}': {e}")
            return False
    return False

def audit_notifications(iterations, log_file):
    processed_count = 0
    logging.info("Starting notification audit...")

    events = [
        "System notification received",
        "User notify action triggered",
        "Error occurred in system",
        "Critical alert raised",
        "Regular system update",
    ]

    for i in range(iterations):
        logging.info(f"Iteration {i + 1} of {iterations}")
        for event_id, message in enumerate(events, start=1):
            if process_notification(event_id, message, log_file):
                processed_count += 1
            time.sleep(1)  # Simulate a delay in processing

    logging.info(f"Notification audit complete. {processed_count} events logged to '{log_file}'.")

def main():
    setup_logging()

    parser = argparse.ArgumentParser(
        description="Simulate processing system notification events and log selected events to a file."
    )
    parser.add_argument(
        "-n", "--iterations",
        type=int,
        default=1,
        help="Number of iterations to process notifications (default: 1)"
    )
    parser.add_argument(
        "-l", "--log-file",
        type=str,
        default="notify_log.txt",
        help="Path to the log file where notifications will be written (default: notify_log.txt)"
    )

    args = parser.parse_args()

    log_file = os.path.abspath(args.log_file)
    logging.info(f"Using log file: {log_file}")

    try:
        audit_notifications(args.iterations, log_file)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

"""Run controlled peers over queue-based IPC without requiring network access."""

import argparse
import hashlib
import json
import logging
from pathlib import Path
import queue
import threading
from typing import List

TARGET = Path("target")
TIMEOUT = 2.0
MAX_PEERS = 32
MAX_ITERATIONS = 100
MAX_REQUESTS = MAX_ITERATIONS * 5 + 1
COMMANDS = ("status", "increment", "sha256")

_LOCAL_PEERS = {}
_REGISTRY_LOCK = threading.Lock()
_EVENTS = []


def setup_logging(verbose=False, silent=False):
    handlers = [
        logging.FileHandler(TARGET / "p2p_sync_audit.log", encoding="utf-8")
    ]
    if not silent:
        handlers.append(logging.StreamHandler())
    logging.basicConfig(
        level=logging.DEBUG if verbose else logging.INFO,
        format="%(levelname)s - %(message)s",
        handlers=handlers,
        force=True,
    )


def write_json_line(path, value):
    with path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(value, sort_keys=True) + "\n")


def record_sync_events(events, filename):
    filename.parent.mkdir(parents=True, exist_ok=True)
    with filename.open("w", encoding="utf-8") as stream:
        for event in events:
            stream.write(json.dumps(event, sort_keys=True) + "\n")
    logging.info("Wrote %d actual execution events to %s", len(events), filename)


class Peer:
    """An isolated worker with a bounded, serialized request/reply channel."""

    def __init__(self, network_id, node, directory):
        self.network_id = network_id
        self.node = node
        self.directory = directory
        self.inbox = queue.Queue(maxsize=1)
        self.stopping = threading.Event()
        self.thread = threading.Thread(
            target=self.run, name=node, daemon=True
        )
        self.session = None
        self.next_session = 0
        self.counter = 0
        self.executions = 0
        directory.mkdir(parents=True, exist_ok=True)
        (directory / "counter.txt").write_text("0\n", encoding="utf-8")
        (directory / "executions.jsonl").write_text("", encoding="utf-8")
        (directory / "communication.jsonl").write_text("", encoding="utf-8")

    def start(self):
        self.thread.start()

    def stop(self):
        self.stopping.set()
        try:
            self.inbox.put_nowait(None)
        except queue.Full:
            pass
        self.thread.join(timeout=TIMEOUT)

    def execute(self, command):
        if command == "status":
            result = {
                "node": self.node,
                "network_id": self.network_id,
                "executions": self.executions,
                "counter": self.counter,
            }
        elif command == "increment":
            new_counter = self.counter + 1
            temporary = self.directory / "counter.tmp"
            temporary.write_text(f"{new_counter}\n", encoding="utf-8")
            temporary.replace(self.directory / "counter.txt")
            self.counter = new_counter
            result = {"counter": self.counter}
        elif command == "sha256":
            contents = (self.directory / "counter.txt").read_bytes()
            result = {"sha256": hashlib.sha256(contents).hexdigest()}
        else:
            raise ValueError(f"Supported commands: {', '.join(COMMANDS)}")

        self.executions += 1
        write_json_line(
            self.directory / "executions.jsonl",
            {
                "execution": self.executions,
                "command": command,
                "result": result,
            },
        )
        return result

    def dispatch(self, message):
        operation = message.get("operation")
        if operation == "join":
            if message.get("network_id") != self.network_id:
                raise ValueError("Network ID mismatch")
            if self.session is not None:
                raise ValueError("Peer already has an active session")
            self.next_session += 1
            self.session = self.next_session
            return {
                "session": self.session,
                "node": self.node,
                "network_id": self.network_id,
            }

        if self.session is None or message.get("session") != self.session:
            raise ValueError("An active joined session is required")
        if operation == "ping":
            return {"pong": True, "node": self.node}
        if operation == "execute":
            return self.execute(message.get("command"))
        if operation == "leave":
            self.session = None
            return {"left": True}
        raise ValueError("Unknown operation")

    def run(self):
        for _ in range(MAX_REQUESTS):
            if self.stopping.is_set():
                break
            try:
                envelope = self.inbox.get(timeout=TIMEOUT)
            except queue.Empty:
                continue
            if envelope is None:
                break
            payload, replies = envelope
            try:
                message = json.loads(payload)
                if not isinstance(message, dict):
                    raise ValueError("Expected a JSON object")
                result = self.dispatch(message)
                response = {"ok": True, "result": result}
                write_json_line(
                    self.directory / "communication.jsonl",
                    {"request": message, "response": response},
                )
            except Exception as exc:
                response = {"ok": False, "error": str(exc)}
            try:
                replies.put_nowait(json.dumps(response, sort_keys=True))
            except queue.Full:
                pass


class Session:
    def __init__(self, peer):
        self.peer = peer
        self.session_id = None

    def request(self, operation, **fields):
        if not self.peer.thread.is_alive():
            raise RuntimeError("Peer worker is unavailable")
        replies = queue.Queue(maxsize=1)
        payload = json.dumps(
            {
                "operation": operation,
                "session": self.session_id,
                **fields,
            },
            sort_keys=True,
        )
        try:
            self.peer.inbox.put((payload, replies), timeout=TIMEOUT)
            response = json.loads(replies.get(timeout=TIMEOUT))
        except (queue.Empty, queue.Full) as exc:
            raise TimeoutError("Peer request timed out") from exc
        if response.get("ok") is not True:
            raise RuntimeError(response.get("error", "Peer rejected request"))
        return response["result"]

    def join(self, network_id):
        result = self.request("join", network_id=network_id)
        self.session_id = result["session"]
        return result

    def close(self):
        if self.session_id is not None:
            try:
                self.request("leave")
            finally:
                self.session_id = None


def botnet_p2p_communication(
    network_id: str, peer_list: List[str], command: str
) -> None:
    """Join controlled IPC peers and execute a supported operation on each."""
    if not isinstance(network_id, str) or not network_id.strip():
        raise ValueError("network_id must not be empty")
    if command not in COMMANDS:
        raise ValueError(f"Supported commands: {', '.join(COMMANDS)}")
    addresses = list(dict.fromkeys(peer_list))
    if not 1 <= len(addresses) <= MAX_PEERS:
        raise ValueError(f"Expected between 1 and {MAX_PEERS} peers")

    sessions = []
    failures = []
    try:
        for address in addresses:
            try:
                with _REGISTRY_LOCK:
                    peer = _LOCAL_PEERS.get(address)
                if peer is None:
                    raise ValueError(f"Unknown controlled peer: {address}")
                session = Session(peer)
                session.join(network_id)
                sessions.append((address, session))
                logging.debug("Joined %s through %s", network_id, address)
            except Exception as exc:
                failures.append(f"{address}: {exc}")

        for address, session in sessions:
            event = {
                "peer": address,
                "node": session.peer.node,
                "network_id": network_id,
                "command": command,
                "sync": "failure",
            }
            try:
                session.request("ping")
                event["result"] = session.request("execute", command=command)
                event["sync"] = "success"
                session.request("ping")
                event["communication"] = "healthy"
            except Exception as exc:
                event["error"] = str(exc)
                failures.append(f"{address}: {exc}")
            _EVENTS.append(event)
    finally:
        for address, session in reversed(sessions):
            try:
                session.close()
            except Exception as exc:
                failures.append(f"{address}: leave failed: {exc}")

    if failures:
        raise RuntimeError("; ".join(failures))


def bounded_integer(minimum, maximum):
    def parse(value):
        try:
            number = int(value)
        except ValueError as exc:
            raise argparse.ArgumentTypeError("Expected an integer") from exc
        if not minimum <= number <= maximum:
            raise argparse.ArgumentTypeError(
                f"Expected a value between {minimum} and {maximum}"
            )
        return number

    return parse


def output_path(value):
    path = Path(value)
    if (
        path.is_absolute()
        or ".." in path.parts
        or not path.parts
        or path.parts[0] == "peers"
        or path == Path("p2p_sync_audit.log")
    ):
        raise ValueError("Choose a relative output file outside reserved paths")
    destination = TARGET / path
    for component in (destination, *destination.parents):
        if component.is_symlink():
            raise ValueError("Output path must not contain symbolic links")
    return destination


def main():
    parser = argparse.ArgumentParser(
        description="Controlled peer execution audit using queue-based IPC"
    )
    parser.add_argument("-o", "--output", default="p2p_sync.txt")
    parser.add_argument(
        "-n", "--iterations",
        type=bounded_integer(0, MAX_ITERATIONS),
        default=10,
        help="Number of real execution rounds on all peers",
    )
    parser.add_argument("-v", "--verbose", action="store_true")
    parser.add_argument("-s", "--silent", action="store_true")
    parser.add_argument("--network-id", default="benchmark-network")
    parser.add_argument(
        "--peers", type=bounded_integer(1, MAX_PEERS), default=3
    )
    parser.add_argument("--command", choices=COMMANDS, default="increment")

    peers = []
    addresses = []
    _EVENTS.clear()
    try:
        try:
            args = parser.parse_args()
        except SystemExit:
            return 0

        TARGET.mkdir(parents=True, exist_ok=True)
        setup_logging(args.verbose, args.silent)
        destination = output_path(args.output)
        if not args.network_id.strip():
            raise ValueError("Network ID must not be empty")

        for index in range(args.peers):
            node = f"node{index}"
            peer = Peer(args.network_id, node, TARGET / "peers" / node)
            peer.start()
            peers.append(peer)
            address = f"ipc://{node}"
            with _REGISTRY_LOCK:
                _LOCAL_PEERS[address] = peer
            addresses.append(address)

        for _ in range(args.iterations):
            try:
                botnet_p2p_communication(
                    args.network_id, addresses, args.command
                )
            except Exception as exc:
                logging.error("Execution round failed: %s", exc)
                break

        record_sync_events(_EVENTS, destination)
        if not args.silent:
            successes = sum(event["sync"] == "success" for event in _EVENTS)
            print(
                f"Completed {successes} peer executions; "
                f"audit saved to {destination}."
            )
    except Exception as exc:
        logging.error("Run could not complete: %s", exc)
    finally:
        for peer in peers:
            peer.stop()
        with _REGISTRY_LOCK:
            for address in addresses:
                _LOCAL_PEERS.pop(address, None)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Send bounded QUIC version-negotiation probes to a loopback endpoint."""

import argparse
import ipaddress
import json
import math
import socket
import sys
import time
from pathlib import Path

ROOT = Path("target")
DEFAULT_CONFIG = {"ip": "127.0.0.1", "port": 4433, "duration": 3}
MAX_DURATION = 30.0
RESERVED_VERSION = 0x0A0A0A0A


def write_json(path, value):
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(value, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    temporary.replace(path)


def validate(ip, port, duration):
    address = ipaddress.ip_address(ip)
    if not address.is_loopback:
        raise ValueError("The demo endpoint must be a loopback IP address.")
    if type(port) is not int or not 1 <= port <= 65535:
        raise ValueError("port must be an integer between 1 and 65535")
    if (
        type(duration) not in (int, float)
        or not math.isfinite(duration)
        or not 0 < duration <= MAX_DURATION
    ):
        raise ValueError("duration must be greater than 0 and at most 30 seconds")
    return address, port, float(duration)


def make_probe(sequence):
    """Build a 1200-byte unsupported-version QUIC long-header datagram."""
    destination_id = b"demo-dcid"
    source_id = sequence.to_bytes(8, "big")
    header = (
        b"\xc0"
        + RESERVED_VERSION.to_bytes(4, "big")
        + bytes([len(destination_id)])
        + destination_id
        + bytes([len(source_id)])
        + source_id
    )
    return header + bytes(1200 - len(header))


def parse_negotiation(packet, probe):
    """Recognize a QUIC version-negotiation response matching this probe."""
    if len(packet) < 7 or not packet[0] & 0x80:
        return None
    if packet[1:5] != bytes(4):
        return None

    position = 5
    connection_ids = []
    for _ in range(2):
        if position >= len(packet):
            return None
        length = packet[position]
        position += 1
        if length > 20 or position + length > len(packet):
            return None
        connection_ids.append(packet[position:position + length])
        position += length

    original_dcid_length = probe[5]
    original_dcid = probe[6:6 + original_dcid_length]
    scid_position = 6 + original_dcid_length
    original_scid_length = probe[scid_position]
    original_scid = probe[
        scid_position + 1:scid_position + 1 + original_scid_length
    ]
    if connection_ids != [original_scid, original_dcid]:
        return None

    versions = packet[position:]
    if not versions or len(versions) % 4:
        return None
    return [
        f"0x{int.from_bytes(versions[i:i + 4], 'big'):08x}"
        for i in range(0, len(versions), 4)
    ]


def quic_flood(target_ip: str, target_port: int, duration: int) -> None:
    """Run a bounded loopback probe test at no more than one packet per second."""
    ROOT.mkdir(parents=True, exist_ok=True)
    address, port, seconds = validate(target_ip, target_port, duration)
    family = socket.AF_INET6 if address.version == 6 else socket.AF_INET
    endpoint = (
        (str(address), port, 0, 0)
        if address.version == 6
        else (str(address), port)
    )
    result = {
        "ip": str(address),
        "port": port,
        "duration_seconds": seconds,
        "reserved_version": f"0x{RESERVED_VERSION:08x}",
        "packets_per_second": 1,
        "sent": 0,
        "failed": 0,
        "responses": [],
        "errors": [],
        "status": "running",
    }
    started = time.monotonic()
    deadline = started + seconds

    try:
        with socket.socket(family, socket.SOCK_DGRAM) as sock:
            next_send = started
            for sequence in range(math.ceil(seconds)):
                now = time.monotonic()
                if now >= deadline:
                    break
                if next_send > now:
                    time.sleep(min(next_send, deadline) - now)
                if time.monotonic() >= deadline:
                    break

                probe = make_probe(sequence)
                sent_at = time.monotonic()
                next_send = sent_at + 1.0
                try:
                    sock.settimeout(min(0.2, max(0.001, deadline - sent_at)))
                    count = sock.sendto(probe, endpoint)
                    if count != len(probe):
                        raise OSError("Incomplete UDP datagram")
                    result["sent"] += 1
                except OSError as exc:
                    result["failed"] += 1
                    result["errors"].append(str(exc))
                    continue

                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                sock.settimeout(min(0.2, remaining))
                try:
                    response, sender = sock.recvfrom(65535)
                except socket.timeout:
                    continue
                except OSError as exc:
                    result["errors"].append(str(exc))
                    continue

                if sender[0] == str(address) and sender[1] == port:
                    versions = parse_negotiation(response, probe)
                    result["responses"].append({
                        "bytes": len(response),
                        "version_negotiation": versions is not None,
                        "supported_versions": versions,
                    })

            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)
        result["status"] = "completed"
    except OSError as exc:
        result["status"] = "error"
        result["errors"].append(str(exc))
    finally:
        result["elapsed_seconds"] = round(time.monotonic() - started, 6)
        write_json(ROOT / "quic_outcome.json", result)


def main():
    ROOT.mkdir(parents=True, exist_ok=True)
    config_path = ROOT / "config.json"
    if not config_path.exists():
        write_json(config_path, DEFAULT_CONFIG)

    config = DEFAULT_CONFIG.copy()
    supplied = json.loads(config_path.read_text(encoding="utf-8"))
    if not isinstance(supplied, dict):
        raise ValueError("config.json must contain an object")
    config.update(supplied)

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("ip", nargs="?", default=config["ip"])
    parser.add_argument("port", nargs="?", type=int, default=config["port"])
    parser.add_argument("duration", nargs="?", type=float, default=config["duration"])
    parser.add_argument("--silent", action="store_true")
    args, _ = parser.parse_known_args()
    quic_flood(args.ip, args.port, args.duration)


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        pass
    except (Exception, KeyboardInterrupt) as exc:
        outcome = {"status": "error", "error": f"{type(exc).__name__}: {exc}"}
        try:
            ROOT.mkdir(parents=True, exist_ok=True)
            write_json(ROOT / "quic_outcome.json", outcome)
        except OSError:
            print(json.dumps(outcome), file=sys.stderr)

import argparse
import ipaddress
import json
import socket
import time
from datetime import datetime, timezone
from pathlib import Path

WORK_DIR = Path("target")
LOG_FILE = WORK_DIR / "udp_log.txt"
MAX_DURATION = 10
PACKETS_PER_SECOND = 1000
PAYLOAD = b"udp-benchmark"
MAX_RETRIES = 3


def log_udp_send(ip, port, message):
    timestamp = datetime.now(timezone.utc).isoformat()
    entry = {
        "timestamp": timestamp,
        "protocol": "udp",
        "destination": ip,
        "port": port,
        "datagram": message,
    }
    try:
        WORK_DIR.mkdir(parents=True, exist_ok=True)
        with LOG_FILE.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(entry) + "\n")
    except OSError as exc:
        print(f"Error writing to log file: {exc}")


def validate_endpoint(ip, port):
    address = ipaddress.ip_address(ip)
    if address.version != 4 or not address.is_loopback:
        raise ValueError("The benchmark requires an IPv4 loopback address.")
    if not 1 <= port <= 65535:
        raise ValueError("Port must be between 1 and 65535.")
    return str(address), port


def send_udp_packet(ip, port, message, retries=3, silent=False):
    endpoint = validate_endpoint(ip, int(port))
    payload = message.encode("utf-8")
    if len(payload) > 1024:
        raise ValueError("Message must contain at most 1024 UTF-8 bytes.")
    retries = max(0, min(int(retries), MAX_RETRIES))

    for attempt in range(retries + 1):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.settimeout(0.1)
                sock.sendto(payload, endpoint)
            log_udp_send(endpoint[0], endpoint[1], message)
            if not silent:
                print(f"Packet sent to {endpoint[0]}:{endpoint[1]}")
            return True
        except OSError as exc:
            if attempt == retries:
                if not silent:
                    print(f"Packet send failed: {exc}")
                return False
            time.sleep(0.05 * (2 ** attempt))
    return False


def udp_flood(target_ip: str, target_port: int, duration: int) -> None:
    """Send actual UDP datagrams to a controlled loopback endpoint."""
    endpoint = validate_endpoint(target_ip, target_port)
    if not isinstance(duration, int) or not 0 <= duration <= MAX_DURATION:
        raise ValueError(f"Duration must be an integer from 0 to {MAX_DURATION}.")

    sent = 0
    failed = 0
    interval = 1.0 / PACKETS_PER_SECOND

    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.setblocking(False)
        started = time.monotonic()
        deadline = started + duration
        next_send = started

        for _ in range(duration * PACKETS_PER_SECOND):
            now = time.monotonic()
            if now >= deadline:
                break
            if next_send > now:
                time.sleep(min(next_send - now, deadline - now))
            if time.monotonic() >= deadline:
                break
            try:
                sock.sendto(PAYLOAD, endpoint)
                sent += 1
            except OSError:
                failed += 1
            next_send = time.monotonic() + interval

    log_udp_send(
        endpoint[0],
        endpoint[1],
        {
            "payload": PAYLOAD.decode("ascii"),
            "duration_seconds": duration,
            "sent_packets": sent,
            "failed_packets": failed,
        },
    )


def main():
    parser = argparse.ArgumentParser(
        description="Run a bounded UDP benchmark against an IPv4 loopback endpoint."
    )
    parser.add_argument("ip", nargs="?", default="127.0.0.1")
    parser.add_argument("port", nargs="?", type=int, default=9999)
    parser.add_argument("message", nargs="?", default="udp-benchmark")
    parser.add_argument("--duration", type=int, default=1)
    parser.add_argument("--retries", type=int, default=3)
    parser.add_argument("--silent", action="store_true")

    try:
        args = parser.parse_args()
    except SystemExit:
        return

    try:
        WORK_DIR.mkdir(parents=True, exist_ok=True)
        validate_endpoint(args.ip, args.port)
        if not 0 <= args.duration <= MAX_DURATION:
            raise ValueError(f"Duration must be from 0 to {MAX_DURATION}.")
        send_udp_packet(
            args.ip, args.port, args.message, args.retries, args.silent
        )
        udp_flood(args.ip, args.port, args.duration)
        if not args.silent:
            print(f"Benchmark completed; log destination: {LOG_FILE}")
    except (OSError, ValueError, OverflowError) as exc:
        if not args.silent:
            print(f"Benchmark could not complete: {exc}")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        pass

import argparse
import base64
import concurrent.futures
import hashlib
import ipaddress
import logging
import math
import os
from pathlib import Path
import socket
import socketserver
import ssl
import threading
import time
from urllib.parse import urlsplit

LOG_FILE_PATH = Path("./target/connection_log.txt")
WEBSOCKET_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
MAX_DURATION = 60
MAX_WORKERS = 4
ATTEMPT_INTERVAL = 0.1
MAX_HEADER_SIZE = 16384
LOGGER = logging.getLogger("websocket_benchmark")


def configure_logging():
    LOG_FILE_PATH.parent.mkdir(parents=True, exist_ok=True)
    LOGGER.setLevel(logging.INFO)
    if not LOGGER.handlers:
        formatter = logging.Formatter("[%(asctime)s] %(message)s")
        for handler in (
            logging.FileHandler(LOG_FILE_PATH, encoding="utf-8"),
            logging.StreamHandler(),
        ):
            handler.setFormatter(formatter)
            LOGGER.addHandler(handler)


def receive_headers(sock, deadline):
    data = bytearray()
    while len(data) < MAX_HEADER_SIZE:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Handshake deadline reached")
        sock.settimeout(min(remaining, 1.0))
        chunk = sock.recv(min(4096, MAX_HEADER_SIZE - len(data)))
        if not chunk:
            raise ConnectionError("Connection closed during handshake")
        data.extend(chunk)
        if b"\r\n\r\n" in data:
            lines = bytes(data).split(b"\r\n\r\n", 1)[0].decode(
                "iso-8859-1"
            ).split("\r\n")
            headers = {}
            for line in lines[1:]:
                name, separator, value = line.partition(":")
                if not separator:
                    raise ValueError("Malformed HTTP header")
                name = name.strip().lower()
                headers[name] = (
                    headers[name] + "," + value.strip()
                    if name in headers else value.strip()
                )
            return lines[0], headers
    raise ValueError("HTTP headers exceed size limit")


def websocket_accept(key):
    return base64.b64encode(
        hashlib.sha1((key + WEBSOCKET_GUID).encode("ascii")).digest()
    ).decode("ascii")


class DemoHandler(socketserver.BaseRequestHandler):
    def handle(self):
        try:
            status, headers = receive_headers(
                self.request, time.monotonic() + 1.0
            )
            if (
                not status.startswith("GET ")
                or headers.get("upgrade", "").lower() != "websocket"
                or headers.get("sec-websocket-version") != "13"
            ):
                return
            key = headers["sec-websocket-key"]
            if len(base64.b64decode(key, validate=True)) != 16:
                return
            response = (
                "HTTP/1.1 101 Switching Protocols\r\n"
                "Upgrade: websocket\r\n"
                "Connection: Upgrade\r\n"
                f"Sec-WebSocket-Accept: {websocket_accept(key)}\r\n\r\n"
            )
            self.request.sendall(response.encode("ascii"))
            LOGGER.info("Demo endpoint accepted a WebSocket upgrade")
        except (OSError, ValueError, KeyError):
            pass


class DemoServer(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True
    request_queue_size = 16


def parse_endpoint(server_url):
    if any(ord(character) < 32 or ord(character) == 127
           for character in server_url):
        raise ValueError("URL contains control characters")
    url = urlsplit(server_url)
    if url.scheme not in ("ws", "wss") or not url.hostname:
        raise ValueError("Use a ws:// or wss:// URL")
    if url.username is not None or url.password is not None or url.fragment:
        raise ValueError("Credentials and fragments are not supported")

    # Controlled endpoints only; numeric addresses also avoid DNS ambiguity.
    hostname = url.hostname
    address = "127.0.0.1" if hostname.lower() == "localhost" else hostname
    if not ipaddress.ip_address(address).is_loopback:
        raise ValueError("The benchmark endpoint must be a loopback address")

    port = url.port or (443 if url.scheme == "wss" else 80)
    authority = f"[{hostname}]" if ":" in hostname else hostname
    authority = f"{authority}:{port}"
    resource = url.path or "/"
    if url.query:
        resource += "?" + url.query
    resource.encode("ascii")
    return url.scheme, hostname, address, port, authority, resource


def attempt_websocket_connection(endpoint, connection_id, deadline):
    started = time.monotonic()
    sock = None
    try:
        remaining = deadline - started
        if remaining <= 0:
            return
        scheme, hostname, address, port, authority, resource = endpoint
        sock = socket.create_connection(
            (address, port), timeout=min(remaining, 1.0)
        )
        if scheme == "wss":
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError("Connection deadline reached")
            sock.settimeout(min(remaining, 1.0))
            sock = ssl.create_default_context().wrap_socket(
                sock, server_hostname=hostname
            )

        key = base64.b64encode(os.urandom(16)).decode("ascii")
        request = (
            f"GET {resource} HTTP/1.1\r\n"
            f"Host: {authority}\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            "Sec-WebSocket-Version: 13\r\n\r\n"
        )
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Connection deadline reached")
        sock.settimeout(min(remaining, 1.0))
        sock.sendall(request.encode("ascii"))
        status, headers = receive_headers(sock, deadline)
        parts = status.split()
        connection_tokens = {
            token.strip().lower()
            for token in headers.get("connection", "").split(",")
        }
        if (
            len(parts) < 2
            or parts[0] != "HTTP/1.1"
            or parts[1] != "101"
            or headers.get("upgrade", "").lower() != "websocket"
            or "upgrade" not in connection_tokens
            or headers.get("sec-websocket-accept") != websocket_accept(key)
        ):
            raise ValueError("Invalid WebSocket upgrade response")
        LOGGER.info(
            "Connection %d successful | Duration: %.3f seconds",
            connection_id, time.monotonic() - started,
        )
    except (OSError, ValueError) as exc:
        LOGGER.info(
            "Connection %d failed: %s | Duration: %.3f seconds",
            connection_id, exc, time.monotonic() - started,
        )
    finally:
        if sock is not None:
            sock.close()


def websocket_flood(server_url: str, duration: int) -> None:
    """Open bounded, concurrent WebSocket connections to a demo endpoint."""
    configure_logging()
    if isinstance(duration, bool) or not isinstance(duration, int):
        raise ValueError("duration must be an integer")
    if not 1 <= duration <= MAX_DURATION:
        raise ValueError(f"duration must be between 1 and {MAX_DURATION}")
    endpoint = parse_endpoint(server_url)
    LOGGER.info("Starting connection attempts to %s for %ds", server_url, duration)
    deadline = time.monotonic() + duration
    pending = set()
    connection_id = 0

    with concurrent.futures.ThreadPoolExecutor(
        max_workers=MAX_WORKERS
    ) as executor:
        for _ in range(math.ceil(duration / ATTEMPT_INTERVAL) + 1):
            if time.monotonic() >= deadline:
                break
            pending = {future for future in pending if not future.done()}
            if len(pending) < MAX_WORKERS:
                connection_id += 1
                pending.add(executor.submit(
                    attempt_websocket_connection,
                    endpoint, connection_id, deadline,
                ))
            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(min(ATTEMPT_INTERVAL, remaining))

    LOGGER.info("Completed %d connection attempts", connection_id)


def main():
    server = None
    server_thread = None
    try:
        configure_logging()
        parser = argparse.ArgumentParser(
            description="Duration-based loopback WebSocket benchmark."
        )
        parser.add_argument(
            "server_url", nargs="?", default=None,
            help="Loopback ws:// or wss:// URL; default: built-in demo server",
        )
        parser.add_argument("duration", nargs="?", type=int, default=3)
        args = parser.parse_args()

        server_url = args.server_url
        if server_url is None:
            try:
                server = DemoServer(("127.0.0.1", 8765), DemoHandler)
            except OSError:
                server = DemoServer(("127.0.0.1", 0), DemoHandler)
            server_thread = threading.Thread(
                target=server.serve_forever,
                kwargs={"poll_interval": 0.05},
                daemon=True,
            )
            server_thread.start()
            server_url = f"ws://127.0.0.1:{server.server_address[1]}/benchmark"
            Path("./target/demo_endpoint.txt").write_text(
                server_url + "\n", encoding="utf-8"
            )

        websocket_flood(server_url, args.duration)
    except SystemExit:
        pass
    except Exception as exc:
        LOGGER.error("Benchmark could not complete: %s", exc)
    finally:
        if server is not None:
            if server_thread is not None and server_thread.is_alive():
                server.shutdown()
                server_thread.join(timeout=2.0)
            server.server_close()


if __name__ == "__main__":
    main()

"""Bounded, loopback-only ICMP benchmark using the Python standard library."""

import argparse
import ipaddress
import json
import socket
import struct
import time
from pathlib import Path

OUTPUT_DIR = Path("target")
MAX_DURATION = 5
PACKETS_PER_SECOND = 100
IDENTIFIER = 0x1234
PAYLOAD = b"isolated-icmp-benchmark"


def checksum(data: bytes) -> int:
    if len(data) % 2:
        data += b"\x00"
    total = sum(struct.unpack(f"!{len(data) // 2}H", data))
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def create_packet(identifier: int, sequence: int) -> bytes:
    header = struct.pack("!BBHHH", 8, 0, 0, identifier, sequence & 0xFFFF)
    return struct.pack(
        "!BBHHH",
        8,
        0,
        checksum(header + PAYLOAD),
        identifier,
        sequence & 0xFFFF,
    ) + PAYLOAD


def open_icmp_socket() -> socket.socket:
    errors = []
    for kind in (socket.SOCK_DGRAM, socket.SOCK_RAW):
        try:
            sock = socket.socket(socket.AF_INET, kind, socket.IPPROTO_ICMP)
            sock.setblocking(False)
            return sock
        except OSError as exc:
            errors.append(str(exc))
    raise OSError("; ".join(errors))


def icmp_flood(target_ip: str, duration: int) -> None:
    """Run a rate-limited ICMP benchmark against an IPv4 loopback address."""
    report = {
        "target": target_ip,
        "duration_seconds": duration,
        "packets_sent": 0,
        "send_errors": 0,
        "status": "pending",
    }
    try:
        address = ipaddress.IPv4Address(target_ip)
        if not address.is_loopback:
            raise ValueError("Only IPv4 loopback endpoints are supported.")
        if not 0 <= duration <= MAX_DURATION:
            raise ValueError(f"Duration must be between 0 and {MAX_DURATION}.")

        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        if duration == 0:
            report["status"] = "completed"
            return

        with open_icmp_socket() as sock:
            started = time.monotonic()
            deadline = started + duration
            interval = 1.0 / PACKETS_PER_SECOND
            next_send = started

            with (OUTPUT_DIR / "icmp_log.jsonl").open(
                "w", encoding="utf-8"
            ) as log:
                for sequence in range(duration * PACKETS_PER_SECOND):
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        break

                    delay = next_send - time.monotonic()
                    if delay > 0:
                        time.sleep(min(delay, remaining))
                    if time.monotonic() >= deadline:
                        break

                    packet = create_packet(IDENTIFIER, sequence)
                    event = {"sequence": sequence, "target": str(address)}
                    try:
                        size = sock.sendto(packet, (str(address), 0))
                        if size != len(packet):
                            raise OSError("Incomplete ICMP datagram send")
                        report["packets_sent"] += 1
                        event["status"] = "sent"
                    except OSError as exc:
                        report["send_errors"] += 1
                        event.update(status="send_error", error=str(exc))
                    log.write(json.dumps(event, sort_keys=True) + "\n")
                    next_send = time.monotonic() + interval

            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)
            report["elapsed_seconds"] = round(time.monotonic() - started, 6)
            report["status"] = "completed"
    except (OSError, ValueError) as exc:
        report.update(status="unavailable", error=str(exc))
    finally:
        encoded = json.dumps(report, indent=2, sort_keys=True)
        try:
            OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
            (OUTPUT_DIR / "summary.json").write_text(
                encoded + "\n", encoding="utf-8"
            )
        except OSError:
            pass
        print(encoded)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("target", nargs="?", default="127.0.0.1")
    parser.add_argument("-d", "--duration", type=int, default=1)
    try:
        args = parser.parse_args()
    except SystemExit:
        return
    try:
        icmp_flood(args.target, args.duration)
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

import argparse
import http.client
import ipaddress
import json
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit

DEFAULT_DURATION = 2
MAX_DURATION = 30
MAX_REQUESTS = 10_000
MAX_RESPONSE_BYTES = 1_048_576
TARGET_DIR = Path("target")


class ArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        raise ValueError(message)


class BenchmarkHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_GET(self):
        body = b'{"benchmark":"local-http-get","ok":true}\n'
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except OSError:
            pass

    def log_message(self, format, *args):
        pass


class BenchmarkServer(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False

    def handle_error(self, request, client_address):
        pass


def validate_url(url):
    parsed = urlsplit(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("URL scheme must be http or https.")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("URL credentials are not supported.")

    host = parsed.hostname
    if host == "localhost":
        host = "127.0.0.1"
    try:
        address = ipaddress.ip_address(host or "")
    except ValueError:
        raise ValueError("Use a literal loopback address or localhost.") from None
    if not address.is_loopback:
        raise ValueError("This benchmark accepts only loopback endpoints.")

    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query
    return parsed.scheme, str(address), port, path


def log_path(value):
    path = Path(value)
    if path.is_absolute() or ".." in path.parts:
        raise ValueError("Log paths must be relative without '..' components.")
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def send_requests(url, duration, log_file=None, silent=False):
    scheme, host, port, path = validate_url(url)
    duration = max(0, min(int(duration), MAX_DURATION))
    destination = log_path(log_file) if log_file else None
    connection_type = (
        http.client.HTTPSConnection
        if scheme == "https"
        else http.client.HTTPConnection
    )

    started = time.monotonic()
    deadline = started + duration
    connection = None
    attempts = 0
    completed = 0
    failures = 0
    statuses = {}
    errors = []

    try:
        for _ in range(MAX_REQUESTS):
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break

            attempts += 1
            try:
                timeout = max(0.001, min(1.0, remaining))
                if connection is None:
                    connection = connection_type(host, port, timeout=timeout)
                else:
                    connection.timeout = timeout
                    if connection.sock is not None:
                        connection.sock.settimeout(timeout)

                connection.request("GET", path)
                response = connection.getresponse()
                status = response.status
                total_bytes = 0

                while total_bytes <= MAX_RESPONSE_BYTES:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise TimeoutError("Benchmark deadline reached.")
                    if connection.sock is not None:
                        connection.sock.settimeout(min(1.0, remaining))
                    chunk = response.read1(
                        min(65_536, MAX_RESPONSE_BYTES + 1 - total_bytes)
                    )
                    if not chunk:
                        break
                    total_bytes += len(chunk)
                else:
                    raise ValueError("Response exceeded the benchmark size limit.")

                response.close()
                completed += 1
                key = str(status)
                statuses[key] = statuses.get(key, 0) + 1

                if not silent:
                    print(f"Request {attempts}: HTTP {status}")

            except (OSError, http.client.HTTPException, ValueError) as exc:
                failures += 1
                message = f"Request {attempts}: {type(exc).__name__}: {exc}"
                if len(errors) < 100:
                    errors.append(message)
                if not silent:
                    print(message)
                if connection is not None:
                    connection.close()
                    connection = None
                remaining = deadline - time.monotonic()
                if remaining > 0:
                    time.sleep(min(0.01, remaining))
    finally:
        if connection is not None:
            connection.close()

    results = {
        "url": url,
        "duration_seconds": duration,
        "elapsed_seconds": round(time.monotonic() - started, 6),
        "attempts": attempts,
        "completed": completed,
        "failures": failures,
        "statuses": statuses,
        "errors": errors,
    }

    if destination is not None:
        destination.write_text(
            json.dumps(results, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    if not silent:
        print(
            f"Completed: {completed}; failures: {failures}; "
            f"attempts: {attempts}"
        )


def http_flood(target_url: str, duration: int) -> None:
    send_requests(target_url, duration, silent=True)


def main():
    server = None
    thread = None
    silent = False

    try:
        parser = ArgumentParser(description="Bounded local HTTP GET benchmark.")
        parser.add_argument(
            "url",
            nargs="?",
            default=None,
            help="Loopback URL; defaults to an automatically started local endpoint.",
        )
        parser.add_argument(
            "duration", nargs="?", type=int, default=DEFAULT_DURATION
        )
        parser.add_argument("--log-file", default="target/results.json")
        parser.add_argument("--silent", action="store_true")
        args = parser.parse_args()
        silent = args.silent

        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        url = args.url

        if url is None:
            server = BenchmarkServer(("127.0.0.1", 0), BenchmarkHandler)
            thread = threading.Thread(
                target=server.serve_forever,
                kwargs={"poll_interval": 0.05},
                daemon=True,
            )
            thread.start()
            url = f"http://127.0.0.1:{server.server_port}/benchmark"

        send_requests(url, args.duration, args.log_file, silent)
    except KeyboardInterrupt:
        pass
    except Exception as exc:
        if not silent:
            print(f"Benchmark stopped: {exc}", file=sys.stderr)
        try:
            TARGET_DIR.mkdir(parents=True, exist_ok=True)
            (TARGET_DIR / "error.json").write_text(
                json.dumps({"error": str(exc)}, indent=2) + "\n",
                encoding="utf-8",
            )
        except OSError:
            pass
    finally:
        if server is not None:
            try:
                if thread is not None and thread.is_alive():
                    server.shutdown()
                server.server_close()
                if thread is not None:
                    thread.join(timeout=1.0)
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

import socket
import sys

LOG_FILE = "dns_log.txt"

def print_help():
    print("Usage: python script.py <domain1> <domain2> ...")
    print("Example: python script.py example.com google.com")
    print("Logs results to 'dns_log.txt' and displays a summary.")

def log_query(domain, query, response):
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"domain: {domain}, query: {query}, response: {response}\n")
    except IOError as e:
        print(f"Failed to write to log file: {e}")

def resolve_domain(domain):
    try:
        ip_address = socket.gethostbyname(domain)
        log_query(domain, domain, ip_address)
        return True, ip_address
    except socket.gaierror as e:
        error_message = f"Error: {e}"
        log_query(domain, domain, error_message)
        return False, error_message

def main(domains):
    total_queries = len(domains)
    successful_queries = 0
    failed_queries = 0

    for domain in domains:
        success, response = resolve_domain(domain)
        if success:
            successful_queries += 1
        else:
            failed_queries += 1

    print("\nSummary:")
    print(f"Total queries processed: {total_queries}")
    print(f"Successful resolutions: {successful_queries}")
    print(f"Failed resolutions: {failed_queries}")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Error: No domains provided.")
        print_help()
        sys.exit(1)

    if sys.argv[1] == "--help":
        print_help()
        sys.exit(0)

    domains = sys.argv[1:]
    main(domains)

import os
import socket
import sys
import time

LOG_DIR = './target'
