def log_request(target_ip, status, mode):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - Target: {target_ip}, Mode: {mode}, Status: {status}\n"
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(log_entry)

def ensure_log_directory():
    if not os.path.exists(LOG_DIR):
        os.makedirs(LOG_DIR)

def send_ntp_requests(target_ip, num_requests, interval, mode):
    ntp_data = b'\x1b' + 47 * b'\0'  # NTP request packet
    server_address = (target_ip, 123)  # NTP uses port 123

    for i in range(num_requests):
        try:
            if mode == 'live':
                with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                    sock.sendto(ntp_data, server_address)
            log_request(target_ip, 'Success', mode)
        except Exception as e:
            log_request(target_ip, f'Failure: {e}', mode)
        time.sleep(interval)

def main():
    if len(sys.argv) < 4:
        print("Usage: python ntp_simulator.py <target_ip> <num_requests> <mode> [interval]")
        print("  <mode>: 'live' or 'offline'")
        print("  [interval]: Optional time interval between requests in seconds (default: 1)")
        sys.exit(1)

    target_ip = sys.argv[1]
    try:
        num_requests = int(sys.argv[2])
    except ValueError:
        print("Error: <num_requests> must be an integer.")
        sys.exit(1)

    mode = sys.argv[3].lower()
    if mode not in ['live', 'offline']:
        print("Error: <mode> must be 'live' or 'offline'.")
        sys.exit(1)

    interval = 1  # Default interval
    if len(sys.argv) == 5:
        try:
            interval = float(sys.argv[4])
            if interval < 0:
                raise ValueError
        except ValueError:
            print("Error: [interval] must be a non-negative number.")
            sys.exit(1)

    ensure_log_directory()

    try:
        send_ntp_requests(target_ip, num_requests, interval, mode)
        print(f"Completed {num_requests} NTP requests to {target_ip} in {mode} mode. Logs saved to {LOG_FILE}")
    except KeyboardInterrupt:
        print("Program interrupted. Exiting cleanly...")
        sys.exit(0)

if __name__ == "__main__":
    main()

import argparse
import datetime
import ipaddress
import json
import math
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

LOG_FILE = "http_test_results.log"

DEFAULT_URL = "http://127.0.0.1:8000"
DEFAULT_PAYLOAD = {"test": "default"}
DEFAULT_DURATION = 10.0

BODY_BYTE_INTERVAL = 0.25
MAX_DURATION = 60.0


def log_to_file(timestamp, status_code, response_time_ms):
    with open(LOG_FILE, "a") as log_file:
        log_file.write(
            f"{timestamp}, Status: {status_code}, "
            f"Response Time: {response_time_ms} ms\n"
        )


def validate_url(url):
    parsed = urllib.parse.urlsplit(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("Expected an HTTP or HTTPS URL.")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("URL credentials are not supported.")
    if parsed.fragment:
        raise ValueError("URL fragments are not supported.")
    try:
        address = ipaddress.ip_address(parsed.hostname or "")
        port = parsed.port
    except ValueError as exc:
        raise ValueError("Use a literal loopback address for the demo endpoint.") from exc
    if not address.is_loopback:
        raise ValueError("The demo endpoint must use a loopback address.")
    if port is not None and port < 1:
        raise ValueError("Invalid port.")


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def slow_body(data, deadline):
    """Transfer a finite body one byte at a time on a single connection."""
    for offset in range(len(data)):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Test duration elapsed.")
        if offset:
            time.sleep(min(BODY_BYTE_INTERVAL, remaining))
            if time.monotonic() >= deadline:
                raise TimeoutError("Test duration elapsed.")
        yield data[offset:offset + 1]


def send_post_requests(url, payload, duration):
    validate_url(url)
    if not math.isfinite(duration) or not 0 < duration <= MAX_DURATION:
        raise ValueError(f"Duration must be between 0 and {MAX_DURATION} seconds.")

    data = json.dumps(payload).encode("utf-8")
    headers = {
        "Content-Type": "application/json",
        "Content-Length": str(len(data)),
        "Connection": "close",
    }
    opener = urllib.request.build_opener(
        urllib.request.ProxyHandler({}),
        NoRedirectHandler(),
    )
    start_time = time.monotonic()
    deadline = start_time + duration

    request_count = 0
    while time.monotonic() < deadline:
        req = urllib.request.Request(
            url,
            data=slow_body(data, deadline),
            headers=headers,
            method="POST",
        )
        request_start_time = time.monotonic()

        try:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            with opener.open(req, timeout=min(1.0, remaining)) as response:
                response_time_ms = int(
                    (time.monotonic() - request_start_time) * 1000
                )
                timestamp = datetime.datetime.now().isoformat()
                log_to_file(timestamp, response.status, response_time_ms)
                print(
                    f"Request {request_count + 1}: Status {response.status}, "
                    f"Response Time: {response_time_ms} ms"
                )
        except urllib.error.URLError as e:
            response_time_ms = int(
                (time.monotonic() - request_start_time) * 1000
            )
            timestamp = datetime.datetime.now().isoformat()
            log_to_file(timestamp, "Error", response_time_ms)
            print(
                f"Request {request_count + 1}: Failed with error: {e.reason}, "
                f"Response Time: {response_time_ms} ms"
            )
        except Exception as e:
            response_time_ms = int(
                (time.monotonic() - request_start_time) * 1000
            )
            timestamp = datetime.datetime.now().isoformat()
            log_to_file(timestamp, "Error", response_time_ms)
            print(
                f"Request {request_count + 1}: Failed with unexpected error: {e}, "
                f"Response Time: {response_time_ms} ms"
            )

        request_count += 1
        remaining = deadline - time.monotonic()
        if remaining > 0:
            time.sleep(min(0.1, remaining))

    print(f"Test completed: Sent {request_count} requests in {duration} seconds.")


def http_slow_post(target_url: str, duration: int) -> None:
    """Run a bounded, sequential slow-body test against a local demo endpoint."""
    send_post_requests(target_url, DEFAULT_PAYLOAD, duration)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Send HTTP POST requests to a target server over a specified duration.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument("--url", default=DEFAULT_URL, help="Target server URL")
    parser.add_argument(
        "--payload",
        default=json.dumps(DEFAULT_PAYLOAD),
        help="JSON payload to include in the POST body",
    )
    parser.add_argument(
        "--duration",
        type=float,
        default=DEFAULT_DURATION,
        help="Test duration in seconds (must be positive)",
    )

    args = parser.parse_args()

    if not math.isfinite(args.duration) or args.duration <= 0:
        print("Error: Duration must be a positive number.")
        sys.exit(1)
    if args.duration > MAX_DURATION:
        print(f"Error: Duration must not exceed {MAX_DURATION} seconds.")
        sys.exit(1)

    try:
        payload = json.loads(args.payload)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON payload: {e}")
        sys.exit(1)

    try:
        validate_url(args.url)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    send_post_requests(args.url, payload, args.duration)

