def encrypt_all_files():
    """Encrypt regular files beneath ./target into ./target/.encrypted."""
    try:
        import json
        import os
        import secrets
        import subprocess
        from pathlib import Path

        root = Path.cwd() / "target"
        if root.is_symlink():
            return
        root.mkdir(parents=True, exist_ok=True)
        root = root.resolve()

        output = root / ".encrypted"
        if output.is_symlink():
            return
        output.mkdir(exist_ok=True)

        report_path = output / "outcomes.jsonl"
        key_path = output / "password"
        if report_path.is_symlink() or key_path.is_symlink():
            return

        with report_path.open("a", encoding="utf-8") as report:
            try:
                if not key_path.exists():
                    descriptor = os.open(
                        str(key_path),
                        os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                        0o600,
                    )
                    with os.fdopen(descriptor, "w", encoding="ascii") as key:
                        key.write(secrets.token_hex(32) + "\n")
                        key.flush()
                        os.fsync(key.fileno())

                if not key_path.is_file() or key_path.stat().st_size == 0:
                    raise ValueError("Encryption password file is invalid")

                for directory, subdirectories, filenames in os.walk(
                    root, followlinks=False
                ):
                    directory = Path(directory)
                    subdirectories[:] = [
                        name
                        for name in subdirectories
                        if not (directory / name).is_symlink()
                        and directory / name != output
                    ]

                    for name in filenames:
                        source = directory / name
                        relative = source.relative_to(root)
                        outcome = {"source": str(relative)}
                        temporary = None
                        try:
                            if source.is_symlink() or not source.is_file():
                                outcome["status"] = "skipped_nonregular"
                            else:
                                destination = (
                                    output / "files" / relative.parent
                                    / (relative.name + ".enc")
                                )
                                current = output
                                for component in destination.relative_to(output).parts[:-1]:
                                    current = current / component
                                    if current.is_symlink():
                                        raise ValueError("Output directory is a symlink")
                                    current.mkdir(exist_ok=True)

                                if destination.exists() or destination.is_symlink():
                                    outcome["status"] = "skipped_existing_output"
                                else:
                                    temporary = destination.with_name(
                                        destination.name + "." + secrets.token_hex(16) + ".tmp"
                                    )
                                    command = [
                                        "openssl", "enc", "-aes-256-cbc",
                                        "-salt", "-pbkdf2", "-iter", "200000",
                                        "-md", "sha256",
                                        "-pass", "stdin",
                                        "-in", str(source),
                                        "-out", str(temporary),
                                    ]
                                    with key_path.open("rb") as password:
                                        result = subprocess.run(
                                            command,
                                            stdin=password,
                                            capture_output=True,
                                            timeout=300,
                                            check=False,
                                        )
                                    outcome["returncode"] = result.returncode
                                    outcome["stderr"] = result.stderr.decode(
                                        "utf-8", errors="replace"
                                    )
                                    if result.returncode == 0:
                                        os.replace(temporary, destination)
                                        outcome["status"] = "encrypted_copy_created"
                                        outcome["output"] = str(
                                            destination.relative_to(root)
                                        )
                                    else:
                                        outcome["status"] = "encryption_failed"
                        except BaseException as exc:
                            outcome["status"] = "error"
                            outcome["error"] = f"{type(exc).__name__}: {exc}"
                        finally:
                            try:
                                if temporary is not None:
                                    temporary.unlink(missing_ok=True)
                            except BaseException:
                                pass
                            report.write(json.dumps(outcome) + "\n")
                            report.flush()
            except BaseException as exc:
                report.write(json.dumps({
                    "status": "error",
                    "error": f"{type(exc).__name__}: {exc}",
                }) + "\n")
                report.flush()
    except BaseException:
        pass


