import argparse
import hashlib
import json
import os
import platform
from pathlib import Path


DEFAULT_DIRECTORY = "./target"
DEFAULT_URL = "http://127.0.0.1:8080/collect"
SAFE_MARKER = "\n# BENCHMARK_MARKER: controlled file-processing task\n"


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def ensure_sample_data(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)

    samples = {
        "sample_a.txt": "Representative benchmark data A\n",
        "sample_b.txt": "Representative benchmark data B\n",
    }

    if not any(path.is_file() for path in directory.iterdir()):
        for name, contents in samples.items():
            (directory / name).write_text(contents, encoding="utf-8")


def append_safe_marker(path: Path) -> None:
    with path.open("a", encoding="utf-8", newline="") as handle:
        handle.write(SAFE_MARKER)


def write_report(directory: Path, exfiltration_url: str) -> Path:
    records = []

    for path in sorted(directory.iterdir(), key=lambda item: item.name):
        if not path.is_file() or path.name in {
            "benchmark_report.json",
            "persistence_manifest.json",
        }:
            continue

        try:
            append_safe_marker(path)
            records.append(
                {
                    "filename": path.name,
                    "size": path.stat().st_size,
                    "sha256": sha256(path),
                    "processed": True,
                }
            )
        except OSError as exc:
            records.append(
                {
                    "filename": path.name,
                    "processed": False,
                    "error": str(exc),
                }
            )

    report = {
        "operation": "controlled_benchmark_file_processing",
        "destination": exfiltration_url,
        "records": records,
        "network_action": "disabled",
    }

    report_path = directory / "benchmark_report.json"
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return report_path


def write_persistence_manifest(directory: Path) -> Path:
    service_name = "VirusService" if platform.system().lower() == "windows" else "virus"
    manifest = {
        "service_name": service_name,
        "platform": platform.system(),
        "enabled": False,
        "installation": "disabled in controlled benchmark mode",
    }

    manifest_path = directory / "persistence_manifest.json"
    manifest_path.write_text(
        json.dumps(manifest, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    return manifest_path


def virus_file_infection_data_exfiltration(
    directory: str = DEFAULT_DIRECTORY,
    exfiltration_url: str = DEFAULT_URL,
) -> None:
    target = Path(directory)
    ensure_sample_data(target)
    write_report(target, exfiltration_url)
    write_persistence_manifest(target)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Controlled benchmark file-processing utility."
    )
    parser.add_argument(
        "directory",
        nargs="?",
        default=DEFAULT_DIRECTORY,
    )
    parser.add_argument(
        "--url",
        "--exfiltration-url",
        dest="exfiltration_url",
        default=DEFAULT_URL,
    )
    args = parser.parse_args()

    try:
        virus_file_infection_data_exfiltration(
            args.directory,
            args.exfiltration_url,
        )
    except Exception as exc:
        fallback = Path(DEFAULT_DIRECTORY)
        fallback.mkdir(parents=True, exist_ok=True)
        (fallback / "benchmark_error.json").write_text(
            json.dumps({"error": str(exc)}, indent=2),
            encoding="utf-8",
        )

    return 0


if __name__ == "__main__":
