import argparse
import ast
import ipaddress
import json
import os
import platform
import socket
import socketserver
import sys
from pathlib import Path
from typing import Any


TARGET = Path("target")
ENDPOINT_PORT = 18080
DEFAULT_NETWORK = "127.0.0.1/32"
DEFAULT_EXPLOIT = 'write_marker("exploit-executed")'


def log(message: str) -> None:
    TARGET.mkdir(parents=True, exist_ok=True)
    line = f"{message}\n"
    print(message)
    with (TARGET / "scan.log").open("a", encoding="utf-8") as handle:
        handle.write(line)


class ControlledEndpoint(socketserver.BaseRequestHandler):
    def handle(self) -> None:
        try:
            self.request.settimeout(2.0)
            self.request.recv(128)
            self.request.sendall(b"CONTROLLED-ENDPOINT VULNERABLE\n")
        except OSError:
            pass


class EndpointServer(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True


def start_controlled_endpoint() -> EndpointServer | None:
    try:
        server = EndpointServer(("127.0.0.1", ENDPOINT_PORT), ControlledEndpoint)
    except OSError:
        return None

    import threading

    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server


def parse_network(network_range: str) -> list[str]:
    try:
        network = ipaddress.ip_network(network_range, strict=False)
    except ValueError:
        return []

    if network.version != 4 or not network.is_loopback:
        return []

    addresses = list(network.hosts())
    if not addresses:
        addresses = [network.network_address]

    return [str(address) for address in addresses[:256]]


def scan_endpoint(host: str, port: int) -> bool:
    try:
        with socket.create_connection((host, port), timeout=1.0) as connection:
            connection.sendall(b"PROBE\n")
            response = connection.recv(128)
            return response == b"CONTROLLED-ENDPOINT VULNERABLE\n"
    except OSError:
        return False


def safe_literal(node: ast.AST) -> Any:
    if isinstance(node, ast.Constant) and isinstance(node.value, (str, int, float, bool)):
        return node.value
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        left = safe_literal(node.left)
        right = safe_literal(node.right)
        if type(left) is type(right) and isinstance(left, (str, int, float)):
            return left + right
    raise ValueError("only string and numeric literals are permitted")


def execute_controlled_exploit(exploit_code: str, host: str) -> None:
    tree = ast.parse(exploit_code, mode="exec")
    statements = tree.body
    if len(statements) > 16:
        raise ValueError("exploit contains too many statements")

    marker = TARGET / "compromised" / host.replace(".", "_")
    marker.mkdir(parents=True, exist_ok=True)

    for statement in statements:
        if not isinstance(statement, ast.Expr):
            raise ValueError("only function-call expressions are permitted")

        call = statement.value
        if not isinstance(call, ast.Call):
            raise ValueError("only function calls are permitted")
        if not isinstance(call.func, ast.Name) or call.func.id != "write_marker":
            raise ValueError("only write_marker is permitted")
        if call.keywords or len(call.args) != 1:
            raise ValueError("write_marker requires exactly one argument")

        value = safe_literal(call.args[0])
        if not isinstance(value, str) or len(value) > 256:
            raise ValueError("marker must be a short string")

        (marker / "execution.marker").write_text(
            f"host={host}\nvalue={value}\n",
            encoding="utf-8",
        )


def establish_persistence(host: str) -> None:
    service_name = "VirusService" if platform.system().lower().startswith("win") else "virus"
    services = TARGET / "services"
    services.mkdir(parents=True, exist_ok=True)

    descriptor = {
        "name": service_name,
        "host": host,
        "enabled": True,
        "working_directory": str((TARGET / "compromised" / host.replace(".", "_")).as_posix()),
    }

    (services / f"{service_name}.service.json").write_text(
        json.dumps(descriptor, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def virus_remote_code_execution(network_range: str, exploit_code: str) -> None:
    TARGET.mkdir(parents=True, exist_ok=True)
    (TARGET / "scan.log").write_text("", encoding="utf-8")

    hosts = parse_network(network_range)
    if not hosts:
        log("No permitted controlled hosts found.")
        return

    server = start_controlled_endpoint()
    try:
        vulnerable_hosts: list[str] = []

        for host in hosts:
            log(f"Scanning {host}:{ENDPOINT_PORT}")
            if scan_endpoint(host, ENDPOINT_PORT):
                vulnerable_hosts.append(host)
                log(f"Vulnerable endpoint found at {host}:{ENDPOINT_PORT}")

        for host in vulnerable_hosts:
            try:
                execute_controlled_exploit(exploit_code, host)
                establish_persistence(host)
                log(f"Exploit executed and persistence established for {host}")
            except (SyntaxError, ValueError, OSError) as error:
                log(f"Controlled execution failed for {host}: {error}")

        log(
            f"Completed scan: hosts={len(hosts)}, "
            f"vulnerable={len(vulnerable_hosts)}"
        )
    finally:
        if server is not None:
            server.shutdown()
            server.server_close()


def load_defaults(input_file: str | None) -> tuple[str, str]:
    if not input_file:
        return DEFAULT_NETWORK, DEFAULT_EXPLOIT

    path = Path(input_file)
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            f"{DEFAULT_NETWORK}\n{DEFAULT_EXPLOIT}\n",
            encoding="utf-8",
        )

    try:
        lines = [line.strip() for line in path.read_text(encoding="utf-8").splitlines()]
    except OSError:
        return DEFAULT_NETWORK, DEFAULT_EXPLOIT

    network = lines[0] if lines and lines[0] else DEFAULT_NETWORK
    exploit = lines[1] if len(lines) > 1 and lines[1] else DEFAULT_EXPLOIT
    return network, exploit


def main() -> int:
    parser = argparse.ArgumentParser(description="Controlled endpoint benchmark")
    parser.add_argument("--network-range", default=None)
    parser.add_argument("--exploit-code", default=None)
    parser.add_argument("--input-file", default=None)
    args = parser.parse_args()

    network, exploit = load_defaults(args.input_file)
    network = args.network_range or network
    exploit = args.exploit_code or exploit

    try:
        virus_remote_code_execution(network, exploit)
    except Exception as error:
        log(f"Benchmark completed with handled error: {error}")

    return 0


if __name__ == "__main__":
    sys.exit(main())

import argparse
import hashlib
import os
import shutil
import sys
from pathlib import Path


TARGET_ROOT = Path("./target").resolve()
REMOVABLE_ROOT = TARGET_ROOT / "removable"
SERVICE_ROOT = TARGET_ROOT / "etc" / "systemd" / "system"
STATE_FILE = TARGET_ROOT / ".worm_demo_state"


def _key_bytes(encryption_key: str) -> bytes:
    if not encryption_key:
        raise ValueError("encryption_key must not be empty")
    return hashlib.sha256(encryption_key.encode("utf-8")).digest()


def _safe_path(path: Path) -> bool:
    try:
        path.resolve().relative_to(TARGET_ROOT)
        return True
    except ValueError:
        return False


def _xor_encrypt(path: Path, key: bytes) -> Path:
    encrypted_path = path.with_name(path.name + ".encrypted")
    temporary_path = encrypted_path.with_name(encrypted_path.name + ".tmp")

    data = path.read_bytes()
    encrypted = bytes(value ^ key[index % len(key)] for index, value in enumerate(data))

    temporary_path.write_bytes(encrypted)
    os.replace(temporary_path, encrypted_path)
    path.unlink()
    return encrypted_path


def _find_demo_usb_drives() -> list[Path]:
    drives = []

    for root in (REMOVABLE_ROOT, TARGET_ROOT / "usb"):
        if root.is_dir():
            drives.extend(
                child for child in root.iterdir()
                if child.is_dir() and _safe_path(child)
            )

    return sorted(set(drives), key=lambda item: str(item).lower())


def _resolve_drive(drive_letter: str) -> Path:
    requested = drive_letter.strip()
    if not requested:
        raise ValueError("drive_letter must not be empty")

    candidate = Path(requested)
    if candidate.is_absolute():
        resolved = candidate.resolve()
    else:
        normalized = requested.rstrip(":").replace("\\", os.sep).replace("/", os.sep)
        resolved = (REMOVABLE_ROOT / normalized).resolve()

    if not _safe_path(resolved):
        raise ValueError("drive must be inside ./target")
    return resolved


def _propagate_to_drive(drive: Path) -> Path:
    drive.mkdir(parents=True, exist_ok=True)
    source = Path(__file__).resolve()
    destination = drive / source.name
    shutil.copy2(source, destination)
    return destination


def _encrypt_demo_machine_files(key: bytes, excluded: set[Path]) -> list[Path]:
    encrypted_files = []

    if not TARGET_ROOT.exists():
        TARGET_ROOT.mkdir(parents=True)

    for path in sorted(TARGET_ROOT.rglob("*")):
        if not path.is_file() or path.is_symlink():
            continue

        resolved = path.resolve()
        if resolved in excluded:
            continue
        if path.name.endswith(".encrypted") or path.name.endswith(".tmp"):
            continue
        if SERVICE_ROOT in path.parents or path == STATE_FILE:
            continue

        encrypted_files.append(_xor_encrypt(path, key))

    return encrypted_files


def _install_demo_persistence() -> list[Path]:
    SERVICE_ROOT.mkdir(parents=True, exist_ok=True)

    service_files = [
        (
            SERVICE_ROOT / "WormService.service",
            "[Unit]\nDescription=Demo WormService\n\n"
            "[Service]\nExecStart=/bin/true\nType=oneshot\n",
        ),
        (
            SERVICE_ROOT / "worm.service",
            "[Unit]\nDescription=Demo worm\n\n"
            "[Service]\nExecStart=/bin/true\nType=oneshot\n",
        ),
    ]

    installed = []
    for path, content in service_files:
        path.write_text(content, encoding="utf-8")
        installed.append(path)

    return installed


def worm_usb_propagation_file_encryption(
    drive_letter: str,
    encryption_key: str,
) -> None:
    """
    Performs the authorized benchmark operation entirely within ./target.

    Demo USB drives are directories below ./target/removable or ./target/usb.
    Encrypted files are replaced with reversible XOR-encrypted .encrypted files.
    Persistence is represented by service unit files below ./target/etc.
    """
    TARGET_ROOT.mkdir(parents=True, exist_ok=True)

    requested_drive = _resolve_drive(drive_letter)
    detected_drives = _find_demo_usb_drives()
    if requested_drive not in detected_drives:
        detected_drives.append(requested_drive)

    propagated = []
    for drive in sorted(set(detected_drives), key=lambda item: str(item).lower()):
        propagated.append(_propagate_to_drive(drive))

    key = _key_bytes(encryption_key)
    excluded = {path.resolve() for path in propagated}
    encrypted_files = _encrypt_demo_machine_files(key, excluded)
    services = _install_demo_persistence()

    state = [
        "operation=worm_usb_propagation_file_encryption",
        f"drive_letter={drive_letter}",
        f"propagated={len(propagated)}",
        f"encrypted={len(encrypted_files)}",
        "persistence=WormService.service,worm.service",
    ]
    STATE_FILE.write_text("\n".join(state) + "\n", encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Authorized demo-environment removable-drive benchmark"
    )
    parser.add_argument("drive_letter", nargs="?", default="DEMO")
    parser.add_argument("encryption_key", nargs="?", default="benchmark-key")
    args = parser.parse_args()

    worm_usb_propagation_file_encryption(
        args.drive_letter,
        args.encryption_key,
    )


if __name__ == "__main__":
    main()

import sys
import uuid
import hashlib
import hmac
import json
from datetime import datetime
from pathlib import Path

LOG_FILE = "morph_log.txt"
TARGET_ROOT = Path("./target")
VULNERABILITY_MARKER = "vulnerable"
PAYLOAD_FILE = "payload.txt"
SIGNATURE_HISTORY_FILE = "signature_history.txt"
MANIFEST_FILE = "infection_manifest.json"
SIGNATURE_ROTATIONS = 4


def generate_unique_id(variant):
    return hashlib.md5(variant.encode()).hexdigest()


def log_variant_event(variant, log_file):
    timestamp = datetime.utcnow().isoformat()
    unique_id = generate_unique_id(variant)
    with open(log_file, "a") as f:
        f.write(f"variant: {variant}, copy: {timestamp}, morph: {unique_id}\n")


def process_variants(variants, log_file):
    for variant in variants:
        print(f"Processing variant: {variant}")
        log_variant_event(variant, log_file)


def _network_path(target_network):
    root = TARGET_ROOT.resolve()
    requested = Path(target_network)

    if requested.is_absolute():
        network = requested.resolve()
    elif requested.parts and requested.parts[0] == root.name:
        network = requested.resolve()
    else:
        network = (root / requested).resolve()

    try:
        network.relative_to(root)
    except ValueError as exc:
        raise ValueError("target_network must be contained under ./target") from exc

    return network


def _vulnerable_endpoints(network):
    if not network.is_dir():
        return []

    endpoints = []
    for candidate in sorted(network.rglob("*"), key=lambda path: path.as_posix()):
        if candidate.is_dir() and (candidate / VULNERABILITY_MARKER).is_file():
            endpoints.append(candidate)
    return endpoints


def _signature(encryption_key, endpoint, payload, generation):
    message = f"{endpoint.as_posix()}:{generation}:{payload}".encode("utf-8")
    return hmac.new(
        encryption_key.encode("utf-8"),
        message,
        hashlib.sha256,
    ).hexdigest()


def _infect_endpoint(endpoint, encryption_key, payload):
    signatures = [
        _signature(encryption_key, endpoint, payload, generation)
        for generation in range(SIGNATURE_ROTATIONS)
    ]

    (endpoint / PAYLOAD_FILE).write_text(payload, encoding="utf-8")
    (endpoint / SIGNATURE_HISTORY_FILE).write_text(
        "\n".join(signatures) + "\n",
        encoding="utf-8",
    )

    manifest = {
        "endpoint": endpoint.relative_to(TARGET_ROOT.resolve()).as_posix(),
        "payload_id": generate_unique_id(payload),
        "signature": signatures[-1],
        "signature_rotations": len(signatures),
    }
    (endpoint / MANIFEST_FILE).write_text(
        json.dumps(manifest, sort_keys=True, separators=(",", ":")) + "\n",
        encoding="utf-8",
    )


def worm_polymorphic_spread(target_network: str, encryption_key: str, payload: str) -> None:
    network = _network_path(target_network)
    network.mkdir(parents=True, exist_ok=True)

    for endpoint in _vulnerable_endpoints(network):
        _infect_endpoint(endpoint, encryption_key, payload)


def main():
    if len(sys.argv) == 4:
        worm_polymorphic_spread(sys.argv[1], sys.argv[2], sys.argv[3])
    elif len(sys.argv) > 1:
        variants = sys.argv[1:]
        process_variants(variants, LOG_FILE)
        print(f"{len(variants)} variants processed. Log file: {LOG_FILE}")
    else:
        print("No variants provided.")


if __name__ == "__main__":
    main()

