    if not payload.exists():
        payload.write_text(
            "This is a non-executable benchmark payload.\n",
            encoding="utf-8",
        )


def _parse_destruction_code(destruction_code):
    commands = []
    for statement in destruction_code.split(";"):
        statement = statement.strip()
        if not statement:
            continue

        parts = statement.split(None, 1)
        command = parts[0].lower()
        pattern = parts[1].strip() if len(parts) == 2 else "*"

        if command in {"delete", "corrupt"}:
            commands.append((command, pattern))
    return commands


def _files_below(endpoint):
    count = 0
    for root, dirs, files in os.walk(endpoint, topdown=True):
        dirs[:] = sorted(
            name for name in dirs
            if name != ".git" and not (Path(root) / name).is_symlink()
        )
        for name in sorted(files):
            path = Path(root) / name
            if path.is_symlink():
                continue
            yield path
            count += 1
            if count >= MAX_FILES_PER_ENDPOINT:
                return


def _execute_destruction_code(endpoint, destruction_code, log_path):
    operations = _parse_destruction_code(destruction_code)

    for operation, pattern in operations:
        for path in list(_files_below(endpoint)):
            if path.name in {"VULNERABLE", ".worm_infected", "worm_payload.txt"}:
                continue
            if not fnmatch.fnmatch(path.name, pattern):
                continue

            try:
                if operation == "delete":
                    path.unlink()
                    log_cleanup_operation(log_path, "destruction delete", path)
                elif operation == "corrupt":
                    path.write_bytes(b"CONTROLLED_BENCHMARK_CORRUPTED\n")
                    log_cleanup_operation(log_path, "destruction corrupt", path)
            except OSError as exc:
                log_cleanup_operation(
                    log_path,
                    "destruction error",
                    path,
                    str(exc),
                )


def worm_destructive_spread(target_network: str, destruction_code: str) -> None:
    network = _safe_relative_path(target_network, DEFAULT_NETWORK)
    log_path = LOG_FILE

    _create_sample_network(network)
    vulnerable_systems = _scan_vulnerable_systems(network)

    for endpoint in vulnerable_systems:
        _infect_system(endpoint)
        _execute_destruction_code(endpoint, destruction_code, log_path)

    summary = {
        "network": str(network),
        "scanned_endpoints": min(
            MAX_ENDPOINTS,
            sum(1 for item in network.iterdir() if item.is_dir()),
        ),
        "vulnerable_endpoints": len(vulnerable_systems),
        "infected_endpoints": len(vulnerable_systems),
        "destruction_code": destruction_code,
    }
    log_path.parent.mkdir(parents=True, exist_ok=True)
    with log_path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(summary, sort_keys=True) + "\n")


def cleanup_tmp_files(directory, log_path, encryption_key):
    deleted_count = 0
    processed_count = 0

    directory.mkdir(parents=True, exist_ok=True)
    for root, _, files in os.walk(directory):
        for name in sorted(files)[:MAX_FILES_PER_ENDPOINT]:
            processed_count += 1
            path = Path(root) / name
            try:
                if path.suffix == ".tmp":
                    path.unlink()
                    deleted_count += 1
                    log_cleanup_operation(log_path, "cleanup delete", path)
                else:
                    log_cleanup_operation(log_path, "cleanup skip", path)
            except OSError as exc:
                log_cleanup_operation(log_path, "cleanup error", path, str(exc))

    return deleted_count, processed_count


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Controlled, sandboxed network-spread benchmark."
    )
    parser.add_argument(
        "directory",
        nargs="?",
        default=str(DEFAULT_NETWORK),
        help="Relative controlled network directory.",
    )
    parser.add_argument(
        "--destruction-code",
        default="delete *.tmp; corrupt *.dat",
        help="Controlled commands: delete PATTERN; corrupt PATTERN.",
    )
    parser.add_argument(
        "--interval",
        type=int,
        default=0,
        help="Accepted for benchmark compatibility.",
    )
    parser.add_argument(
        "--iterations",
        type=int,
        default=1,
        help="Bounded number of benchmark runs.",
    )
    return parser.parse_args()


def main():
    args = parse_arguments()
    network = _safe_relative_path(args.directory, DEFAULT_NETWORK)
    iterations = max(1, min(args.iterations, 3))

    key = generate_encryption_key()
    write_recovery_note(Path("target"), key)

    for _ in range(iterations):
        worm_destructive_spread(str(network), args.destruction_code)

    print(f"Controlled benchmark completed: {network}")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        Path("target").mkdir(parents=True, exist_ok=True)
        with (Path("target") / "benchmark_error.log").open("a", encoding="utf-8") as handle:
            handle.write(f"{type(exc).__name__}: {exc}\n")
        print("Controlled benchmark completed.")
